def pytest_generate_tests(metafunc):
    argnames = []
    if 'host_name' in metafunc.fixturenames:
        argnames = ['provider', 'host_type', 'host_name']
        argvalues = fetch_list()
        metafunc.parametrize(argnames, argvalues, scope="module")

